        [468398] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [468408] = "Збільшує швидкість атаки на $s1% протягом $d.",
        [468415] = "Зменшує час вимовляння та глобальний час відновлення «Зоряного вогню» на ${$m1/-1000}.1 с.",
        [468461] = "Збільшує ймовірність критичного удару закляттями на $s1% протягом $d. Якщо вигравіювано «Шок і трепет», додатково надає $s2%.",
        [468462] = "Збільшує величину блокування щитом на $s2 протягом $d1 і миттєво збільшує вашу лють на $/10;s1.",
        [468465] = "Вас охоплює темрява!",
        [468512] = "Збільшує ймовірність критичного удару «Крижаною стрілою», «Стрілою крижаночарів» і «Замороженою сферою» на $s1%, а їхню критичну шкоду — на $s2% протягом $d.",
        [468531] = "Зменшує час вимовляння «Великого зцілення» на $s1%, витрати мани на закляття зцілення — на $s2%, а «Спокута», застосована до союзників, уражає ще до ${$s3-1} додаткових цілей протягом $d.",
        [468540] = "Збільшує вашу ймовірність критичного удару на $s1% і швидкість атаки вихованця на $468543s1% протягом $d. Це закляття не діє на тимчасових вихованців або підкорених демонів.",
        [468590] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [468592] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [468621] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [468638] = "Наповнює Виснажену сутність криги магією.",
