        [468840] = "Поєднайте уламок душі з Виснаженою косою хаосу.",
        [468843] = "Кровоточить, отримуючи $s2 шкоди щосекунди.",
        [468913] = "Збільшує дальність «Святого шоку» на $s1 ярдів, але зменшує всю завдану вами шкоду від святості на $s2%.",
        [468925] = "Швидкість руху зменшено на $s2%.",
