        [469059] = "Посилає у ворога стрілу хаотичного вогню, завдаючи від ${$<power>*$m1/100} до ${$<power>*$M1/100} шкоди від вогню. «Стріла хаосу» завжди влучає, їй неможливо опиратися, а знання цього закляття дозволяє всім вашим вогняним закляттям пробивати ефекти поглинання. «Стріла хаосу» має високу ймовірність опору, якщо її використовувати проти монстрів на 4 або більше рівнів вище за вас.",
        [469105] = "Плює оскверненою кров’ю, завдаючи $469114s1 шкоди від тіні кожні $469110t1 с. Ефект може поширитися на гравців поблизу.",
        [469110] = "Плює оскверненою кров’ю, завдаючи $469114s1 шкоди від тіні кожні $469110t1 с. Ефект може поширитися на гравців поблизу.",
        [469114] = "Плює оскверненою кров’ю, завдаючи $469114s1 шкоди від тіні кожні $469110t1 с. Ефект може поширитися на гравців поблизу.",
        [469115] = "Плює оскверненою кров’ю, завдаючи $469114s1 шкоди від тіні кожні $469110t1 с. Ефект може поширитися на гравців поблизу.",
        [469128] = "Поєднайте з двома іншими частинами, щоб створити Сигіл Хранителя.",
        [469133] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [469138] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [469140] = "Миттєво надає $s1 додаткову атаку обома видами зброї.",
        [469148] = "Збільшує швидкість бігу на $s1% протягом $d1.",
        [469183] = "Прикликані тотеми надають благословення своєї стихії.",
        [469199] = "Охолоджує полум’я Террестріса, загартовуючи його для захисту.",
        [469201] = "Розпалює полум’я Террестріса, нагріваючи його для наступу.",
        [469211] = "Прямі закляття шкоди мають шанс зробити наступне прикликання вихованця протягом $469220d1 миттєвим і таким, що не витрачає уламок душі.",
        [469220] = "Час вимовляння вашого наступного закляття прикликання біса, демона Безодні, сукуба, інкуба, мисливця Скверни або вартового Скверни зменшується на $/1000;s1 с, і воно не витрачає уламка душі чи мани.",
        [469221] = "Пожинає душу вашого прикликаного демона, надаючи ефект на $469224d. Ефект скасовується, якщо прикликати будь-якого демона.",
        [469223] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [469229] = "Ваше наступне «Прокляття мов» накладе на ціль мовчанку на $469227d1. Якщо застосувати його до цілі, що вимовляє закляття, воно перерве вимовляння та не дозволить застосовувати закляття цієї школи протягом $469228d1.",
        [469230] = "Отримувана фізична шкода зменшена на $s1%, а «Демонічний ривок» тепер можна використовувати в бою й він не має часу відновлення.",
        [469236] = "Щоразу, коли ви завдаєте цілі шкоди арканою, залишок часу відновлення «Присутності розуму» зменшується на $s1 с.",
        [469237] = "Якщо вивчено «Покращений опік», цілі, уражені вашою «Вибуховою хвилею», також отримують $s1 накладання «Вразливості до вогню».",
        [469238] = "Поки діє «Крижаний бар’єр», шкода від заклять і ефектів криги збільшується на величину до $s1.",
        [469260] = "Поглинутий бойовим запалом, поступово накопичує лють.",
        [469262] = "Активуйте в Лігві Чорного Крила або на Чорнокамінній горі, щоб замаскуватися під техніка Чорного Крила. ",
        [469320] = "Жбурляєте в ціль розплавлену лаву, завдаючи від ${$m1/100*$<damagepower>} до ${$M1/100*$<damagepower>} шкоди від вогню. Якщо на цілі діє ваш «Вогняний шок», «Виверження лави» завдасть критичного удару.",
        [469357] = "Обпалює ворогів поблизу на ${$<power>*$427725m1/100} шкоди щоразу, коли ворог атакує вас у ближньому бою (не частіше разу на секунду), зменшує всю отримувану магічну шкоду на $s2% і збільшує завдану шкоду від вогню на $s3%. Триває $d.",
        [469371] = "Випускає у ворога крижану стрілу, завдаючи від ${$m1/100*$<power>} до ${$M1/100*$<power>} шкоди від криги.",
        [469410] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [469414] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [469481] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
