        [469706] = "Засурміть у ріг, щоб покликати Еонаса назад, якщо ви розділитеся. Це також скасує всі активні магічні маскування.",
        [469777] = "Налаштуйтеся на Лігво Чорного Крила!",
        [469872] = "Телепортує гравця до Зул’Ґуруба.",
        [469891] = "Засурміть у ріг, щоб покликати Еонаса назад, якщо ви розділитеся. Це також скасує всі активні магічні маскування.",
        [469985] = "Носіть знак драконячого посланця, союзника драконячої зграї.",
