        [470079] = "Збільшує шкоду «Зорепаду» на $s1%, але зменшує його радіус на $s2%.",
        [470080] = "«Лютий укус» більше не перетворює додаткову енергію на шкоду й повертає $s1 енергії у разі ухилення, промаху або парирування.",
        [470081] = "Поки у вас споряджений щит, атаки ближнього бою зі «Зброєю каменегриза» спричиняють спрацювання руни «Зброя Виру» на $470082s1% частіше.",
        [470082] = "Збільшує частоту спрацювання «Зброї Виру» на $s1%.",
        [470104] = "Поки вигравіювано «Гуркіт грому», застосування «Виверження лави» мають $s1% шанс додати заряд до активного «Щита блискавок».",
        [470105] = "Ваш талант «Стихійна зосередженість» тепер має максимум ${$s1+1} зарядів і при спрацюванні надає ${$s1+1} зарядів.",
        [470108] = "Ви перетворюєтеся на камінь, стаючи захищеним від усіх фізичних атак і заклять на $d, але в цей час не можете атакувати, рухатися чи вимовляти закляття. Одночасно може діяти ефект лише одного настою.",
        [470235] = "Збільшує бонус сили атаки ударів «Зброї люті вітру» на $s1.",
        [470240] = "Поки на зброї в основній руці діє «Зброя крижаного тавра», спрацювання «Водяного щита» зменшують час вимовляння наступної «Ланцюгової блискавки» протягом $470272d1 на $470272s1% і збільшують її шкоду на $470272s1%. Накопичується до 5 разів.",
        [470246] = "Завдання шкоди «Святим шоком» зменшує час вимовляння та витрати мани наступного «Святого гніву» протягом $470271d1 на $470271s1% і збільшує його шкоду на $470271s4%. Накопичується до 5 разів.",
        [470263] = "«Щит месника» уражає на $s2 цілей менше, але влучає в свою ціль $s1 разів.",
        [470265] = "Жбурляє у ворога святий щит, завдаючи від ${$m1*$<damagepower>/100+0.091*$SPH+0.091*$AP} до ${$M1*$<damagepower>/100+0.091*$SPH+0.091*$AP} шкоди від святості, приголомшуючи його та перескакуючи на інших ворогів поблизу. Уражає загалом $x1 цілей. Триває $d.",
        [470266] = "Збільшує зцілення від «Живлення» на величину до $s1.",
        [470269] = "Збільшує початкову та періодичну шкоду кожного накладання «Роздирання» на $s1.",
        [470361] = "Збільшує шкоду заклять на $s1 протягом $d.",
        [470362] = "Відновлює $o1 здоров’я протягом $d. Під час їжі потрібно залишатися сидячи. Якщо їсти 10 секунд, шкода заклять також збільшиться на $470361s1 протягом $470361d1.",
        [470367] = "Збільшує зцілення на $s1 протягом $d.",
        [470369] = "Відновлює $o1 здоров’я протягом $d. Під час їжі потрібно залишатися сидячи. Якщо їсти 10 секунд, зцілення також збільшиться на $470367s1 протягом $470367d1.",
        [470459] = "Телепортує гравця у відносно безпечне місце.",
        [470460] = "Телепортує гравця у відносно безпечне місце.",
        [470462] = "Запускає в бік випадкового гравця сфери, насичені тінню, які віддаляються та повертаються до точки походження. Уражені гравці отримують $s1 шкоди від тіні",
        [470497] = "Виріжте луску зі шкури Нефаріана. Можна використати лише тоді, коли Нефаріан значно ослаблений у бою.",
        [470537] = "Виріжте луску зі шкури Нефаріана. Можна використати лише тоді, коли Нефаріан значно ослаблений у бою.",
        [470836] = "Створює хмару блискавок на $d, що вражає всіх ворогів у вибраній області на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 с.",
        [470866] = "Створює хмару блискавок на $d, що вражає всіх ворогів у вибраній області на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 с.",
        [471400] = "Створює «Чудовий тролеблиск».",
        [471401] = "Після нанесення на щит збільшує шкоду заклять і зцілення на величину до 36 та ймовірність критичного ефекту заклять на 1%. Триває 30 хвилин.",
        [471699] = "Налаштуйтеся на внутрішню темряву, щоб краще контролювати свого внутрішнього демона.\r\n",
        [473387] = "Згуртовує учасників вашої групи або рейду поблизу, збільшуючи їхню ймовірність критичного ефекту заклять на $s1%, критичного удару ближнього й дальнього бою на $s3% та силу атаки на $s2. Триває $d. Несумісне з подібними світовими ефектами й не залежить від хроноблагословень.",
        [473399] = "Прикликає піснецвіт, що збільшує ймовірність критичного удару ближнього, дальнього бою або закляттям усім учасникам вашої групи чи рейду на $s1%, а характеристики — на $s2 протягом $d. Несумісне з подібними світовими ефектами. Не залежить від хроноблагословень.",
        [473403] = "Надає всім учасникам вашої групи або рейду поблизу $s1 сили атаки, збільшує витривалість на $s3% і ймовірність критичного ефекту заклять на $s4% протягом $d. Несумісне з подібними світовими ефектами. Не залежить від хроноблагословень.",
        [473441] = "Збільшує здоров’я на $s1. Надає $s2% швидкості атак ближнього бою та $s3 відновлення мани кожні 5 секунд.",
        [473450] = "Збільшує всю завдану шкоду всіх учасників вашої групи або рейду на $s1% протягом $d.",
        [473466] = "Прикликає казан вогняної води на $d, яким можуть користуватися всі учасники групи або рейду, щоб збільшити силу атаки ближнього бою на $473469s1 і розмір на $473469d.",
        [473476] = "Збільшує швидкість руху всіх учасників вашої групи або рейду на $s1% і всі характеристики на $s3% протягом $d.",
        [473482] = "Послаблює елементалів Ради Безодні в Силітусі, зменшуючи всю завдану ними шкоду на $s1%. Триває $d.",
        [473493] = "Установлює пастку неподалік, яка вибухає, коли наближається силітид із Вулика Аші, Вулика Реґал або Вулика Зора, завдаючи силітиду шкоди в розмірі $473496s1% його здоров’я кожні $473496t с протягом $473496d.",
        [473525] = "Заморожує силітида у Вулику Аші, Вулику Реґал або Вулику Зора на $d. Будь-яка шкода перериває ефект.",
        [473544] = "Вдихання цих пахощів дозволяє вам розчинитися в тінях і крастися всередині Вулика Аші, Вулика Реґал або Вулика Зора, але зменшує швидкість на $s2%. Триває $d.",
        [473561] = "Киньте стародавню мотузку, щоб зв’язати силітида з Вулика Аші, Вулика Реґал або Вулика Зора та підтягнути його до себе. Не можна використовувати проти ворогів вище ${$PL+1} рівня або позначених як боси.",
        [473702] = "Використайте гілку, щоб покликати Древнього війни на допомогу в битві із силітидами.",
        [474126] = "Збільшує шкоду від заклять і ефектів на величину до $s1.",
        [474127] = "Критичні удари неперіодичних заклять сил природи мають шанс збільшити шкоду ваших заклять на $474126s1 протягом $474126d1.",
        [474142] = "Ваші неперіодичні закляття шкоди збільшують шкоду заклять на $474148s1 протягом $474148d1. Якщо ціль контролюється гравцем, натомість ви отримуєте $474146s2 проникнення заклять на $474146d1.",
        [474148] = "Збільшує шкоду від заклять і ефектів на величину до $s1.",
        [474196] = "Ваші закляття шкоди мають шанс прикликати Видіння кіражських пророків.",
        [474400] = "Тимчасово зводить ворожу ціль з розуму, збільшуючи швидкість її атак на $s2%, руху на $s3% і змушуючи атакувати власних союзників протягом $d. Уражені цілі отримують на $s4% менше шкоди.",
        [474444] = "Завдає звичайної шкоди плюс $s1 ворогам поблизу та підкидає їх у повітря.",
        [474564] = "Громовий удар.",
        [474727] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [1213174] = "Критичні удари «Каліченням», «Шматуванням» і «Лютим укусом» спричиняють кровотечу, що завдає $s1% завданої шкоди протягом наступних $1213176d с.",
        [1213188] = "Щоразу, коли ви ухиляєтеся у формі лютого ведмедя, шкода вашого наступного «Калічення» або «Розмаху» збільшується на $1213190s1%; ефект накопичується до $1213190u разів.",
        [1213196] = "Зменшує час відновлення «Калічення (ведмідь)» на ${$m1/-1000}.1 с.",
        [1213209] = "Збільшує опір закляттям на ${$1213221s1*10} протягом $d. Щоразу, коли ворожe закляття влучає у вас, цей бонус зменшується на $1213221s1 опору.",
        [1213232] = "Поглинає $s1 шкоди від сил природи та знімає з користувача до $s2 отрут. Триває $d.",
        [1213234] = "На мить перебудовує ваше тіло, миттєво знімаючи всі активні ефекти отрути та надаючи несприйнятливість до всієї шкоди від сил природи на $d.",
        [1213238] = "Ваші неперіодичні закляття шкоди збільшують шкоду заклять на $1213241s1 протягом $1213241d1. Якщо ціль контролюється гравцем, натомість ви отримуєте $1213240s1 проникнення заклять на $1213240d1.",
        [1213241] = "Збільшує шкоду від заклять і ефектів на величину до $s1.",
        [1213278] = "Миттєво захищає вас щитом, що поглинає $s1 шкоди. Триває $d. Поки щит тримається, вимовляння заклять не переривається.\r\n",
        [1213289] = "Зменшує ймовірність ухилення або парирування ваших атак на $s1%.",
        [1213290] = "Зменшує ймовірність ухилення або парирування ваших атак на $s1%.",
        [1213297] = "Приймаєте аспект Вартового Рою, атакуючи ворогів поблизу вихором клинків протягом $d.",
        [1213314] = "Ваші «Щит мани», «Вогняний оберіг» і «Крижаний оберіг» поглинають на $s1% більше шкоди та також накладають на ціль «Часовий маяк» на $400735d.",
        [1213318] = "«Спалах вогню» тепер також збільшує ймовірність критичного ефекту вашого наступного вогняного закляття на $1213317s1% протягом $1213317d.",
        [1213335] = "Зариваєтеся в землю, стаючи недоступним для вибору ціллю на $d1.",
        [1213366] = "Збільшує силу атаки на $1213367s1 і ще на $1213367s1 кожні $t1 с. Триває $d.",
        [1213406] = "Ваші звичайні атаки дворучною зброєю ближнього бою збільшують шкоду наступного «Екзорцизму» протягом $1217927d на $1217927s1%. Ефект накопичується до $s1 разів.",
        [1213410] = "«Благословення прихистку» також збільшує всі характеристики на $1213408s1%, якщо застосоване до себе.",
        [1213411] = "Надає власникові $s1% шанс воскреснути з $23700s1% здоров’я та мани. (Мінімальний час відновлення: $1213414s1)",
        [1213417] = "Має шанс уразити ціль ближнього бою блискавкою на $1213418s1 шкоди від сил природи.",
        [1213419] = "Іноді зцілює власника на $1213420s1 під час завдання шкоди ворогові в ближньому бою.",
        [1213421] = "$s1% шанс під час успішного застосування закляття дозволити $1213422s1% відновлення мани тривати під час вимовляння заклять протягом $1213422d.",
        [1213422] = "$1213421s1% шанс під час успішного застосування закляття дозволити $s1% відновлення мани тривати під час вимовляння заклять протягом $d.",
        [1213610] = "Створює Зачарований відлякувач.",
        [1213616] = "Назавжди зачаровує нагрудний обладунок, збільшуючи всі характеристики на 4 та опір силам природи на 15.",
        [1213619] = "Збільшує шкоду від заклять і ефектів святості на величину до $s1.",
        [1213622] = "Назавжди зачаровує рукавички, збільшуючи шкоду від святості на величину до 20.",
        [1213625] = "Збільшує шкоду від заклять і ефектів аркани на величину до $s1.",
        [1213626] = "Назавжди зачаровує рукавички, збільшуючи шкоду від аркани на величину до 20.",
        [1213813] = "Коли вас атакують у бою, завдає нападникові $s1 шкоди від сил природи. Створює удвічі більше загрози, ніж завдано шкоди.",
        [1213816] = "Коли вас атакують у бою, завдає нападникові $s1 шкоди від сил природи. Створює удвічі більше загрози, ніж завдано шкоди.",
        [1213829] = "Назавжди збільшує шкоду заклять і зцілення предмета для нагрудника, ніг, рук або взуття на величину до 10. Можна використовувати лише на предметах 45-го рівня й вище.",
        [1213833] = "Назавжди надає предмету для нагрудника, ніг, рук або взуття ефект, що завдає нападникові 20 шкоди від сил природи, коли вас атакують у бою. Можна використовувати лише на предметах 45-го рівня й вище.",
        [1213834] = "Коли вас атакують у бою, завдає нападникові $s1 шкоди від сил природи. Створює удвічі більше загрози, ніж завдано шкоди.",
        [1213862] = "Коли вас атакують у бою, має $h% шанс викрасти $1213864s1 здоров’я в цільового ворога.",
        [1213874] = "Коли вас атакують у бою, має $h% шанс викрасти $1213873s1 здоров’я в цільового ворога.",
        [1213886] = "Збільшує зцілення від магічних заклять і ефектів на величину до $s1, шкоду — на величину до $s2, а відновлення мани — на $s3 мани кожні 5 секунд протягом $d. Одночасно може діяти ефект лише одного настою. Ефект зберігається після смерті.",
        [1213892] = "Збільшує шкоду від магічних заклять і ефектів на величину до $s1 протягом $d. Одночасно може діяти ефект лише одного настою. Ефект зберігається після смерті.",
        [1213894] = "Зменшує час вимовляння «Ланцюгового зцілення» на ${$m1/-1000}.1 с.",
        [1213897] = "Збільшує силу атаки на $s1 протягом $d. Одночасно може діяти ефект лише одного настою. Ефект зберігається після смерті.",
        [1213901] = "Збільшує витривалість на $s1 і показник захисту на $s2 протягом $d. Одночасно може діяти ефект лише одного настою. Ефект зберігається після смерті.",
        [1213904] = "Збільшує спритність на $s1, ймовірність критичного удару на $s2% та опір силам природи на $s3 протягом $d.",
        [1213914] = "Збільшує шкоду заклять на величину до $s1 та опір силам природи на $s2 протягом $d.",
        [1213917] = "Збільшує броню на $s1, показник захисту на $s2 та опір силам природи на $s3 протягом $d.",
        [1213918] = "Критичні удари «Ударом бурі», «Лавовим батогом» і «Виверженням лави» змушують ціль горіти, отримуючи $s1% завданої шкоди протягом $1213915d.",
        [1213922] = "Збільшує швидкість бігу гравця на $s1% протягом $d.",
        [1213924] = "Висмоктує $s1 мани з усіх у радіусі вибуху та завдає цілі шкоди в розмірі 50% висмоктаної мани. Також накладає мовчанку на уражені цілі на $d.",
        [1213930] = "Завдання шкоди цілі «Ударом бурі», «Виверженням лави» або «Розплавленим вибухом» також зменшує всю отримувану вами шкоду на $1213934s1% протягом $1213934d.",
        [1213935] = "Під час спрацювання вибухає, завдаючи всім ворогам поблизу $s1 шкоди від вогню та $s2 шкоди вам. Завдає додаткової шкоди силітидам у Силітусі.",
        [1213937] = "Коли «Дух Альфи» застосовано до себе, він також збільшує ваше здоров’я на $1213939s1%, створювану загрозу на $1213939s2% і всю завдану шкоду на $1213939s3%.",
        [1213955] = "Розгортається в генератор G00 DV-1B3, який може ремонтувати пошкоджені предмети та купувати непотрібні товари. Через $d його внутрішній двигун відмовляє й потребує відновлення.",
        [1213963] = "Коли щит блокує атаку, він випускає електричний заряд, що завдає шкоди всім ворогам поблизу.",
        [1213967] = "Накопичує енергію в щиті протягом $d, щоб завдати $s1 шкоди від сил природи всім ворогам поблизу. Після використання щиту потрібно $1213968d для перезарядження.",
        [1214001] = "Прочитайте сувій, викликаючи «Гнів Рою», що посилює ваш рейд: шкода та зцілення заклять збільшуються на величину до $s1, а сила атаки — на $s2 протягом $d.",
        [1214004] = "Після нанесення на зброю або щит збільшує шкоду заклять на величину до $1214006s1 і ймовірність критичного ефекту заклять на $1214006s3%. Триває 30 хвилин.",
        [1214037] = "Висмоктує життя з усіх ворогів поблизу.",
        [1214058] = "Збільшує зцілення від «Святого Світла» та «Спалаху Світла» на $s1%.",
        [1214059] = "Збільшує зцілення від «Ланцюгового зцілення» та «Хвилі зцілення» на $s1%.",
        [1214063] = "Збільшує зцілення від «Життєцвіту», «Живлення» та «Дикого зростання» на $s1%.",
        [1214069] = "Під час удару ближнього бою має шанс завдати цілі $s1 шкоди від вогню. Майже кожен удар завдає додаткової шкоди силітидам у Силітусі.",
        [1214070] = "Зменшує всю отримувану шкоду на $s1. ",
        [1214087] = "Щоразу, коли ви вражаєте ціль «Спалахом», ваша шкода від вогню збільшується на $1214088s1% протягом $1214088d; ефект накопичується до $1214088u разів.",
        [1214091] = "Зменшує час відновлення «Тіньового розсічення» на ${$m1/-1000}.1 с.",
        [1214115] = "Пряма шкода закляттями має шанс завдати цілі $s1 шкоди від вогню. Майже кожне влучання завдає додаткової шкоди силітидам у Силітусі.",
        [1214125] = "Пряма шкода закляттями або атака ближнього бою має шанс завдати цілі $1213941s1 шкоди від вогню. Майже кожне влучання завдає додаткової шкоди силітидам у Силітусі.",
        [1214136] = "Через $d завдає великої шкоди, розподіленої між усіма ураженими.",
        [1214143] = "Під час влучання дальньою атакою має шанс завдати цілі $1213941s1 шкоди від вогню. Майже кожне влучання завдає додаткової шкоди силітидам у Силітусі.",
        [1214151] = "Протягом $1214156d після використання «Тіньового розсічення» ваш «Пекучий біль» уражає ще $1214156s1 ціль у радіусі ближнього бою.",
        [1214158] = "Ваше «Очищення» також зцілює ціль на $s1.",
        [1214168] = "Покриває зброю отрутою на 30 хвилин.\r\nКожен удар має 30% шанс отруїти ворога, завдаючи $1214170o1 шкоди від сил природи протягом $1214170d і збільшуючи отримувану ним шкоду від аркани, вогню, криги, сил природи й тіні на $1214170s2%. Накопичується до $1214170u разів на одній цілі.\r\n\r\n«Окультна отрута» вважається «Смертельною отрутою» й отримує переваги від усіх талантів та ефектів, що спрацьовують від «Смертельної отрути» або змінюють її.",
        [1214169] = "Навчає «Окультної отрути» (ранг 2).",
        [1214171] = "Покриває зброю отрутою на 30 хвилин. Кожен удар має $h% шанс отруїти ворога, завдаючи $1214170o1 шкоди від сил природи протягом $1214170d і збільшуючи отримувану ним шкоду від аркани, вогню, криги, сил природи й тіні на $1214170s2%. Накопичується до $1214170u разів на одній цілі.\r\n\r\n«Окультна отрута» вважається «Смертельною отрутою» й отримує переваги від усіх талантів та ефектів, що спрацьовують від «Смертельної отрути» або змінюють її.\r\n",
        [1214204] = "Збільшує зцілення від усіх магічних заклять і ефектів на величину до $s1, а шкоду — на величину до $s2.",
        [1214206] = "Прикликає на ціль переможені щупальця, які переслідують і атакують її протягом $d.",
