        [1217844] = "Ваша шкіра обпалена й почорніла, через що ви отримуєте більше шкоди від «Нестерпної спеки».",
        [1217959] = "Вогонь мерехтить і згасає.",
        [1218038] = "Скутий кригою, доки пута не буде знищено.",
        [1218071] = "Прикликає піснецвіт, що збільшує ймовірність критичного удару ближнього, дальнього бою або закляттям усім учасникам вашої групи чи рейду на $s1%, а характеристики — на $s2 протягом $473399d. Несумісне з подібними світовими ефектами. Не залежить від хроноблагословень.",
        [1218072] = "Надає всім учасникам вашої групи або рейду поблизу $s1 сили атаки, збільшує витривалість на $s3% і ймовірність критичного ефекту заклять на $s4% протягом $473403d. Несумісне з подібними світовими ефектами. Не залежить від хроноблагословень.",
        [1218073] = "Збільшує всю завдану шкоду всіх учасників вашої групи або рейду на $s1% протягом $473450d.",
        [1218074] = "Збільшує здоров’я на $s1. Надає $s2% швидкості атак ближнього бою та $s3 відновлення мани кожні 5 секунд. Триває $473441d.",
        [1218075] = "Збільшує швидкість руху всіх учасників вашої групи або рейду на $s1% і всі характеристики на $s3% протягом $473476d.",
        [1218121] = "Згуртовує учасників вашої групи або рейду поблизу, збільшуючи їхню ймовірність критичного ефекту заклять на $s1%, критичного удару ближнього й дальнього бою на $s3% та силу атаки на $s2. Триває $473387d. Несумісне з подібними світовими ефектами й не залежить від хроноблагословень.",
        [1218198] = "Павучий квартал посилено. Під час бою поблизу випадково з’являтимуться яйцеві мішки, які вибухатимуть через кілька секунд.",
        [1218216] = "Завдає періодичної шкоди від сил природи. Ваші атаки мають шанс породити павучих прислужників, які кидаються на ворогів.",
        [1218240] = "Ви намагаєтеся добити поранену ціль дальньою атакою, що завдає $s2% шкоди зброєю плюс ${$m1/100*$m2/100*$<damagepower>}. «Смертельний постріл» не має мінімальної дальності. Його час відновлення скидається, якщо використати проти ворога з 20% здоров’я або менше.",
        [1218271] = "Сили Скверни стають могутнішими.",
        [1218275] = "Сили Скверни стають могутнішими.",
        [1218276] = "Сили Скверни стають могутнішими.\r\n",
        [1218283] = "Сам Король-Ліч звернув увагу. Тут не лишилося надії.",
        [1218352] = "Надає закляттям шкоди від криги $h% шанс накласти «Зимову стужу», що збільшує ймовірність критичного удару закляттям криги по цілі на $12579s1% протягом $12579d. Накопичується до $12579u разів.",
        [1218358] = "Вводить ціль у скажене шаленство, збільшуючи силу атаки ближнього бою на $s1, але зменшуючи броню на $s2 протягом $d. Скажені вороги не тікають і ігнорують ефекти страху та жаху.",
        [1218366] = "Вас огортає крижана магічна темрява... ",
        [1218367] = "Підніміть Зачарований смолоскип і спробуйте розвіяти темряву біля крипт Каражану.",
        [1218423] = "«Життєцвіт» тепер має $s1% шанс зцілити ціль на величину одного ефекту його розвіювання щоразу, коли ціль отримує шкоду. Ефект може спрацьовувати лише раз на кілька секунд.",
        [1218427] = "Щоразу, коли «Омолодження» 10-го або 11-го рангу зцілює ціль, ви маєте $s1% шанс відновити їй $1219708m1 мани, $1219706m1 енергії або ${$1219707m1/10} люті.",
        [1218429] = "Ваші «Омолодження» та «Відновлення» поновлюються до повної тривалості щоразу, коли їхню ціль пошкоджує невмерлий ворог.",
        [1218443] = "«Місячне сяйво» та «Сонячний вогонь» завдають на $s1% більше шкоди.",
        [1218444] = "Час відновлення «Зоряного сплеску» зменшується на ${$m1/-1000}.1 с.",
        [1218445] = "Коли «Зоряний сплеск» вражає невмерлу ціль, залишок тривалості активного «Зорепаду» поновлюється до $m1 с.",
        [1218476] = "«Граблі» тепер завдають періодичної шкоди кожні $s1 с, збільшуючи загальну періодичну шкоду на $s3%.",
        [1218477] = "Час відновлення «Люті тигра» зменшується на $s1%.",
        [1218478] = "Щоразу, коли ви завдаєте невмерлій цілі шкоди від кровотечі, ваша шкода та критична шкода по невмерлих збільшуються на $1218479s1% протягом $1218479d; ефект накопичується до $1218479u разів.",
        [1218482] = "«Гарчання» ніколи не промахується, а ймовірність ухилення або парирування ваших атак зменшується на $s1%.",
        [1218507] = "Зменшує час відновлення «Інстинктів виживання» на ${$m1/-60000} хв, а «Берсерка» — на ${$m2/-60000} хв.",
        [1218509] = "Коли ви отримуєте шкоду від невмерлого ворога, залишок тривалості активного «Шаленого відновлення» поновлюється до $m1 с. Крім того, «Шалене відновлення» ніколи не витратить ваші останні $s2 люті для зцілення.",
        [1218514] = "«Зміїне жало» завдає на $s1% більше шкоди.",
        [1218515] = "Зменшує час відновлення «Пострілу химери», «Вибухового пострілу» та «Прицільного пострілу» на ${$m1/-1000}.1 с, «Смертельного пострілу» — на ${$m2/-1000} с, а «Мультипострілу» — на ${$m3/-1000} с.",
        [1218575] = "Щоразу, коли ви вражаєте невмерлого ворога дальньою атакою, ваша шкода та критична шкода по невмерлих збільшуються на $1226739s1% протягом $1226739d; ефект накопичується до $1226739u разів.",
        [1218582] = "«Удар віверни» та «Укус мангуста» завдають на $s1% більше початкової шкоди.",
        [1218583] = "Зменшує час відновлення «Удару віверни» на ${$m1/-1000} с, «Удару раптора» — на ${$m2/-1000} с, а «Флангового удару» — на ${$m3/-1000} с.",
        [1218589] = "Щоразу, коли ви вражаєте невмерлого ворога атакою ближнього бою, ваша шкода та критична шкода по невмерлих збільшуються на $1218587s1% протягом $1218587d; ефект накопичується до $1218587u разів. Накладання втрачаються після виконання дальньої атаки.",
        [1218592] = "Союзники з вашим «Часовим маяком» відновлюють ${$SPA*$m1/1000+$<healpower>*$400735m1/100} здоров’я кожні $400735t1 с.",
        [1218693] = "Під час підтримання «Регенерації» ціль отримує $s1% швидкості руху, а щоразу, коли здібність її зцілює, вона має шанс отримати $1218695s2% швидкості атаки й вимовляння заклять на $1218695d.",
        [1218697] = "Шкода, яку ви завдаєте невмерлим, спричиняє на $s1% більше хрономантичного зцілення, а ви отримуєте ману в розмірі $s2% від хрономантичного зцілення, створеного шкодою по невмерлих.",
        [1218700] = "Ваше «Прикликання» щосекунди підтримання надає вам $?a1218232|a1218271|a1218275|a1218276|a1218283|a1224428[$1218701s1%][$1218701s2%] збільшення завданої шкоди; ефект накопичується до $m2 разів і триває $1218701d.",
        [1218993] = "Зменшує час відновлення «Прикликання» на $s1%.",
        [1218995] = "Шкода вашого «Займання» не спадає на невмерлих цілях із запасом здоров’я нижче $s1%, а невмерлі цілі із запасом здоров’я нижче $s2% отримують шкоду так, ніби вони заморожені.",
        [1219010] = "Зменшує час відновлення «Покладання рук» на ${$m1/-60000} хв, а використання «Покладання рук» тепер відновлює вам $m2% максимальної мани.",
        [1219019] = "Періодичні ефекти тіні мають шанс накласти «Повзучу темряву» до $1219020U разів. Закляття, що завдають прямої шкоди від тіні, підривають цей ефект, завдаючи $M1 шкоди за кожне накладання.",
        [1219020] = "Періодичні ефекти тіні мають шанс накласти «Повзучу темряву» до $1219020U разів. Закляття, що завдають прямої шкоди від тіні, підривають цей ефект, завдаючи $M1 шкоди за кожне накладання.",
        [1219024] = "Періодичні ефекти тіні мають шанс накласти «Повзучу темряву» до $1219020U разів. Закляття, що завдають прямої шкоди від тіні, підривають цей ефект, завдаючи $M1 шкоди за кожне накладання.",
        [1219058] = "Військовий квартал посилено. Під час бою випадково надходитимуть накази. Виконуйте їх — або відповідайте за наслідки!",
        [1219059] = "Ваші «Спалах Світла» 6-го рангу та «Святе Світло» 8-го й 9-го рангів мають $h% шанс наповнити ціль Святою силою.",
        [1219060] = "Роби, що наказано!",
        [1219072] = "Збільшує зцілення на $s2% і завдану шкоду на $s1%.",
        [1219073] = "Збільшує шкоду «Повзучої темряви» на $s1%.",
        [1219085] = "Змушений марширувати. Триває, доки ви не засвоїте урок!",
        [1219090] = "Накладає на ціль мовчанку на $d.",
        [1219093] = "Схопіть нитку душі ворога, щоб підтягнути його фізичну оболонку до себе. Не можна використовувати проти ворогів вище ${$PL+1} рівня або позначених як боси.",
        [1219098] = "Ціль вашого «Маяка Світла» отримує на $s1% менше шкоди від невмерлих ворогів.",
        [1219099] = "Карає до $x1 ворогів поблизу ударом тіні, завдаючи кожному $s1 шкоди.\r\n\r\n«Тіньове розсічення» отримує переваги від більшості талантів та ефектів, від яких отримує переваги «Тіньова стріла», і також спричиняє їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s1 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [1219101] = "Час вимовляння вашого наступного закляття прикликання біса, демона Безодні, сукуба, інкуба, мисливця Скверни або вартового Скверни зменшується на $/1000;s1 с, і воно не витрачає уламка душі чи мани.",
        [1219108] = "Військовий квартал посилено. Під час бою випадково надходитимуть накази. Виконуйте їх — або відповідайте за наслідки!",
        [1219110] = "Схопіть нитку душі ворога, щоб підтягнути його фізичну оболонку до себе. Не можна використовувати проти ворогів вище ${$PL+1} рівня або позначених як боси.",
        [1219111] = "Схопіть нитку душі ворога, щоб підтягнути його фізичну оболонку до себе. Не можна використовувати проти ворогів вище ${$PL+1} рівня або позначених як боси.",
        [1219114] = "Чумний квартал посилено. Поблизу випадково виростатимуть підсилювальні гриби, але після дозрівання вони вибухатимуть.",
        [1219121] = "Накладає на ворожу ціль «Криваву чуму», що завдає $M1 шкоди від тіні кожні $t1 с протягом $d.",
        [1219124] = "Накладає на ворожу ціль «Крижану гарячку», що завдає $M1 шкоди від криги кожні $t1 с протягом $d.",
        [1219150] = "Збільшує швидкість атак і вимовляння заклять на $s1%. Збільшує отримувану шкоду від сил природи на $s2%.",
        [1219153] = "Позначає ворога. Щоразу, коли він завдає шкоди, ціль зцілюється на $M1% максимального запасу здоров’я. Триває $d або до $U ударів.\r\n\r\nЗаряди не витрачаються на невмерлих цілях. На цілі одночасно може діяти лише один «Знак крові».",
        [1219161] = "Позначає ворога. Щоразу, коли він завдає шкоди, ціль зцілюється на $M1% максимального запасу здоров’я. Триває $d або до $U ударів.\r\n\r\nЗаряди не витрачаються на невмерлих цілях. На цілі одночасно може діяти лише один «Знак крові».",
        [1219176] = "Знищує ціль, завдаючи $M1 шкоди.\r\n\r\nКожна «Кривава чума» або «Крижана гарячка» на цілі збільшує завдану шкоду на $M2%.",
        [1219178] = "Знищує ціль, завдаючи $M1 шкоди.\r\n\r\nКожна «Кривава чума» або «Крижана гарячка» на цілі збільшує завдану шкоду на $M2%.",
        [1219189] = "Збільшує шкоду «Божественної бурі» на $s1%.",
        [1219191] = "Зменшує час вимовляння «Святого гніву» на $s1%, час відновлення — на $s2%, а витрати мани — на $s3%.",
        [1219193] = "Ваші «Удар хрестоносця», «Божественна буря», «Екзорцизм» і «Святий гнів» завдають невмерлим додаткової шкоди, що дорівнює їхній ймовірності критичного удару.",
        [1219194] = "Чумний квартал посилено. Поблизу випадково виростатимуть підсилювальні гриби, але після дозрівання вони вибухатимуть.",
        [1219195] = "Чумний квартал посилено. Поблизу випадково виростатимуть підсилювальні гриби, але після дозрівання вони вибухатимуть.",
        [1219205] = "«Десниця розплати» ніколи не промахується, а ймовірність ухилення або парирування ваших атак зменшується на $s1%.",
        [1219206] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.\r\n\r\nПоки ви знаєте цю здібність, бонус загрози від «Праведної люті» збільшується до $407627s5%, а зцілення іншими відновлює вам ману в розмірі $407627s4% від величини зцілення. Крім того, поки «Праведна лють» активна, шкода, що знижує ваше здоров’я нижче $407627s6%, зменшується на $407627s7%. «Праведна лють» діє до скасування.",
        [1219225] = "Зменшує час відновлення «Божественного захисту» на ${$m1/-60000} хв, а «Гніву месника» — на ${$m2/-60000} хв.",
        [1219226] = "Коли шкода від невмерлого ворога знижує ваше здоров’я нижче $407627s6%, ефект «Десниці розплати» та «Праведної люті» тепер зменшує цю шкоду на $s1%.",
        [1219229] = "Квартал Конструктів посилено. Випадкові гравці стають цілями енергетичних блискавок.",
        [1219230] = "Зменшує час відновлення «Кола зцілення» та «Спокути» на $s1%.",
        [1219233] = "Ваші «Спокута», «Швидке зцілення» 7-го рангу, «Зв’язувальне зцілення» та «Велике зцілення» 4-го й 5-го рангів мають $h% шанс збільшити ймовірність критичного удару цілі на $1219232s1% протягом $1219232d.",
        [1219234] = "Повітря навколо вас потріскує.",
        [1219235] = "Збільшує швидкість атак і вимовляння заклять. Періодично випускає імпульси блискавки в гравців поблизу.",
        [1219238] = "«Слово сили: Щит» має $s1% шанс не втратити заряд, коли ціль отримує шкоду від невмерлого ворога.",
        [1219242] = "«Слово тіні: Біль» завдає на $s1% більше шкоди.",
        [1219244] = "Зменшує час відновлення «Вибуху розуму» на ${$m/-1000}.1 с.",
        [1219250] = "Ваші «Катування розуму», «Вибух розуму» та «Шип розуму» завдають невмерлим додаткової шкоди, що дорівнює їхній ймовірності критичного удару.",
        [1219260] = "«Засідка» та «Миттєва отрута» завдають на $s1% більше шкоди. «Удар у спину» завдає на $s3% більше шкоди (не впливає на «Калічення»). Ви зцілюєтеся на $s2% від усієї шкоди, завданої вашими отрутами.",
        [1219275] = "Ви отримуєте здібність «Пожираюча чума»:\r\n\r\n$@spellicon19280\r\nЗаражає ціль хворобою, що завдає $o1 шкоди від тіні протягом $d.  Шкода від Пожираючої чуми зцілює заклинача.",
        [1219286] = "Ви маєте $h% шанс отримати $1219288s1 енергії щоразу, коли завдаєте періодичної шкоди від сил природи або кровотечі.",
        [1219293] = "За кожне витрачене очко серії ваша шкода та критична шкода по невмерлих збільшуються на $1219291s1% протягом $1219291d; ефект накопичується до $1219291u разів.",
        [1219338] = "Земля вкрилася кригою, ускладнюючи рух.",
        [1219356] = "«Дражнити» ніколи не промахується, а ймовірність ухилення або парирування ваших атак зменшується на $s1%.",
        [1219358] = "Зменшує час відновлення «Ухилення» на ${$m1/-60000} хв, а «Шквалу клинків» — на ${$m2/-60000} хв.",
        [1219359] = "Будь-яка шкода від невмерлого нападника, яка мала б вас убити, натомість зменшує ваше здоров’я до $s2% максимального запасу (або до поточного запасу, якщо він нижчий). Крім того, вся шкода від невмерлих зменшується на $400024s1% протягом $400024d. Ефект не може спрацьовувати частіше ніж раз на хвилину.",
        [1219361] = "«Земний щит» більше не втрачає зарядів.",
        [1219364] = "Ваші «Хвиля зцілення» 9-го й 10-го рангів та «Мала хвиля зцілення» 6-го рангу мають $h% шанс наповнити ціль Тотемною силою.",
        [1219365] = "Ціль вашого «Духа Альфи» отримує на $s1% менше шкоди від невмерлих ворогів.",
        [1219367] = "Збільшує періодичну шкоду «Вогняного шоку» на $s1%.",
        [1219368] = "Зменшує час відновлення «Виверження лави» на ${$m1/-1000} с.",
        [1219369] = "Щоразу, коли «Перевантаження» спрацьовує від атакувального закляття, ваша шкода та критична шкода по невмерлих збільшуються на $1219370s1% протягом $1219370d; ефект накопичується до $1219370u разів.",
        [1219373] = "Поки вигравіювано «Електростатику», шкода «Щита блискавок» збільшується на $s1%.",
        [1219374] = "Зменшує час відновлення «Лавового батога» та «Удару бурі» на ${$m1/-1000}.1 с.",
        [1219376] = "За кожен отриманий заряд «Зброї Виру» ваша шкода та критична шкода по невмерлих збільшуються на $1219375s1% протягом $1219375d; ефект накопичується до $1219375u разів.",
        [1219382] = "«Земний шок» ніколи не промахується, коли використовується як провокація, а ймовірність ухилення або парирування ваших атак зменшується на $s1%.",
        [1219387] = "Періодично випускає в повітря вогняні стріли, завдаючи $1219388s1 шкоди.",
        [1219389] = "Змушує заклинача автоматично завдавати ворогам поблизу $1219390s1 шкоди від вогню кожні $t1 с. ",
        [1219397] = "Темрява згущується. Ви не можете дихати!",
        [1219413] = "Додатково збільшує зменшення отримуваної шкоди від «Шаманської люті» на $s1%, а під час її дії швидкість атак і вимовляння заклять збільшується на $s2%.",
        [1219414] = "Ви отримуєте на $s1% менше шкоди від невмерлих ворогів.",
        [1219420] = "Провісник гріха створює вогняний вихор, що затягує всіх ворогів усередину протягом дії притягування.",
        [1219421] = "Збільшує шкоду «Спопелення» та «Псування» на $s1%.",
        [1219423] = "Ваші неперіодичні критичні удари змушують активні на цілі «Псування», «Жертовний вогонь», «Тіньове полум’я» та «Нестабільну недугу» миттєво завдати одного спрацювання шкоди з ефективністю $s1%.",
        [1219462] = "«Прокляття агонії» також накладає ефекти «Прокляття нерозважності». Крім того, воно не завершується на невмерлих цілях і безмежно зростає в силі.",
        [1219474] = "«Загроза» ніколи не промахується, а ймовірність ухилення чи парирування ваших атак або промаху заклять зменшується на $s1%.",
        [1219476] = "Зменшує час відновлення «Пекельної броні» на ${$m1/-1000} с, а «Демонічної благодаті» — на ${$m2/-1000} с.",
        [1219479] = "Коли невмерлий ворог намагається атакувати вас, залишок тривалості активної «Помсти» поновлюється до $s1 с.",
        [1219481] = "Збільшує шкоду таланту «Глибокі рани» на $s1%.",
        [1219483] = "Зменшує час відновлення «Кровожерливості», «Смертельного удару» та «Удару щитом» на $s1%.",
        [1219486] = "Критичні удари ближнього бою по невмерлих збільшують вашу шкоду та критичну шкоду по невмерлих на $1219485s1% протягом $1219485d; ефект накопичується до $1219485u разів.",
        [1219501] = "Відбиває наступне атакувальне закляття, спрямоване на користувача, та збільшує опір усім школам магії на $s1 протягом $d.",
        [1219503] = "Зменшує ваш розмір і створювану загрозу на $s1% протягом $d.",
        [1219510] = "Назавжди додає предмету для комірки наплічників збільшення шкоди й зцілення від магічних заклять та ефектів на величину до $1220735s1, а також збільшує ймовірність критичного удару на $1220735s3%.",
        [1219511] = "Назавжди додає предмету для комірки наплічників $1220754s2 витривалості та $1220754s3 захисту. ",
        [1219512] = "Назавжди додає предмету для комірки наплічників $1220743s3 сили атаки та збільшує ймовірність критичного удару на $1220743s2%.",
        [1219539] = "Розкриває ваш потенціал у Наксрамасі, збільшуючи вашу шкоду на ${$m1/100}.2% і здоров’я на ${$m2/100}.2% за кожен одягнений освячений предмет. (Понад $1223336s2 освячених предметів не дають додаткової користі)",
        [1219540] = "«Провокація» ніколи не промахується, а ймовірність ухилення або парирування ваших атак зменшується на $s1%.",
        [1219543] = "Зменшує час відновлення «Стіни щитів» на ${$m1/-60000} хв і «Нерозважності» на ${$m1/-60000} хв. «Нерозважність» тепер можна використовувати в будь-якій стійці, і вона не збільшує отримувану шкоду.",
        [1219544] = "Коли ви отримуєте шкоду від невмерлого ворога, залишок тривалості активного «Останнього рубежу» поновлюється до $m1 с.",
