        [1219752] = "Назавжди насичує ваші наплічники Душею Бездоганного Блокувальника:\r\n\r\nЗбільшує показник блокування вашого щита на $s1.",
        [1219753] = "Назавжди насичує ваші наплічники Душею Дикуна:\r\n\r\nВи отримуєте додатково ${$457648m1/10} люті щоразу, коли отримуєте будь-яку шкоду чи завдаєте удару автоматичною атакою.",
        [1219754] = "Назавжди насичує ваші наплічники Душею Ворожнечі:\r\n\r\nЗбільшує вашу загрозу в захисній стійці додатково на $s1% та збільшує вашу шкоду в стійці гладіатора на $s2%.",
        [1219755] = "Назавжди насичує ваші наплічники Душею Відбивача:\r\n\r\nВи отримуєте ${$468066m1/10} люті щоразу коли парируєте атаку чи вашу атаку парирують.",
        [1219756] = "Назавжди насичує ваші наплічники Душею Месника:\r\n\r\n«Помста» також надає вам «Шквал», збільшуючи швидкість атаки на $12970s1% протягом наступних $12970n ударів.",
        [1219757] = "Назавжди насичує ваші наплічники Душею Невпинного:\r\n\r\nКоли ваша ціль парирує атаку, ви миттєво завдаєте їй «Відплати» на $468071s2% шкоди зброєю. Від «Відплати» не можна ухилитися, її не можна заблокувати чи парирувати, і вона може спрацювати лише раз на $468071d для кожної цілі.",
