        [1219798] = "Назавжди насичує ваші наплічники Душею Пожирача плоті:\r\n\r\nПоки ви націлені на ворога в межах $468029r ярдів, «Витік життя» надає вам ману за рахунок здоров’я цілі, але завдає їй на $s1% менше шкоди. Кількість отриманої мани не змінюється.",
        [1219799] = "Назавжди насичує ваші наплічники Душею Безоднього:\r\n\r\nПоки діє «Метаморфоза», ваші атакувальні здібності та прикликання демонів не витрачають уламків душі. Крім того, коли ви завдаєте цілі шкоди «Опіком тіні», ви зцілюєтеся на $468062s1% максимального запасу здоров’я.",
        [1219800] = "Назавжди насичує ваші наплічники Душею Породженого Порожнечею:\r\n\r\nНадлишкове самозцілення перетворюється на щит, який поглинає шкоду. Цей щит може поглинути до $s1% від вашого максимального запасу здоров'я, а також підсилюється від подальшого самозцілення.",
