        [1219803] = "Назавжди насичує ваші наплічники Душею Розповсюджувача болю:\r\n\r\nПротягом $1214156d після використання «Тіньового розсічення» ваш «Пекучий біль» уражає ще $1214156s1 ціль у радіусі ближнього бою.",
        [1219804] = "Назавжди насичує ваші наплічники Душею Оманника:\r\n\r\nПісля використання «Відволікаючого пострілу» ви створюєте на $456339s1% більше загрози протягом $456339d.",
        [1219805] = "Назавжди насичує ваші наплічники Душею Шукача здобичі:\r\n\r\nПід час вистежування певного типу істот ви завдаєте їм на $s1% більше шкоди.",
        [1219806] = "Назавжди насичує ваші наплічники Душею Влучного стрільця:\r\n\r\nВаша наступна здібність пострілу протягом $456382d після «Прицільного пострілу» завдає на $456382s1% більше шкоди.",
        [1219807] = "Назавжди насичує ваші наплічники Душею Переслідувача небезпеки:\r\n\r\nВаш \"Прицільний постріл\" завдає на $s1% більше шкоди цілям, ураженим однією з ваших пасток.",
        [1219808] = "Назавжди насичує ваші наплічники Душею Чередувача:\r\n\r\nЗдібності-постріли, що завдають шкоди, завдають на $s1% більше шкоди, якщо попередній постріл було застосовано на іншу ціль.",
